    font = QtGui.QFont()
    font.setPointSize(7)
    app.setFont(font)
    MainWindow = QtWidgets.QMainWindow()
    ui = CrackToolsApplication()
    ui.setupUi(MainWindow)
    MainWindow.show()
    sys.exit(app.exec_())